'use client'

import React, { createContext, useContext, useState, useEffect } from 'react';

export type PegSoundOption = 'default' | 'alt' | 'off';

interface SettingsContextType {
  pegSound: PegSoundOption;
  setPegSound: (option: PegSoundOption) => void;
}

const SettingsContext = createContext<SettingsContextType | undefined>(undefined);

export function SettingsProvider({ children }: { children: React.ReactNode }) {
  const [pegSound, setPegSoundState] = useState<PegSoundOption>('default');

  // Load settings from localStorage on mount
  useEffect(() => {
    const stored = localStorage.getItem('peg-sound-setting');
    if (stored && (stored === 'default' || stored === 'alt' || stored === 'off')) {
      setPegSoundState(stored);
    }
  }, []);

  const setPegSound = (option: PegSoundOption) => {
    setPegSoundState(option);
    localStorage.setItem('peg-sound-setting', option);
  };

  return (
    <SettingsContext.Provider value={{ pegSound, setPegSound }}>
      {children}
    </SettingsContext.Provider>
  );
}

export function useSettings() {
  const context = useContext(SettingsContext);
  if (context === undefined) {
    throw new Error('useSettings must be used within a SettingsProvider');
  }
  return context;
}
